package com.zoutrankil.data.service;

import com.zoutrankil.data.domain.*;
import com.zoutrankil.data.repository.MoneyflowWritePort;
import java.nio.file.*;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import java.util.concurrent.CancellationException;
import java.util.function.BooleanSupplier;
import static com.zoutrankil.data.domain.SyncJobDefinition.Mode;

/** Daily-source adapter; preserves complete receipts and refuses silent target key deletion. */
public final class MoneyflowSyncAdapter implements SyncJobRunner.Adapter<Moneyflow,MoneyflowKey> {
    private final MoneyflowSource source;private final MoneyflowTradingDates calendar;private final MoneyflowWritePort port;private final Path evidenceRoot;private final String targetId;
    public MoneyflowSyncAdapter(TusharePageService pages,MoneyflowTradingDates calendar,MoneyflowWritePort port,Path evidenceRoot,String targetId){this.source=new MoneyflowSource(pages,evidenceRoot.resolve("source"));this.calendar=Objects.requireNonNull(calendar);this.port=Objects.requireNonNull(port);this.evidenceRoot=evidenceRoot.toAbsolutePath().normalize();this.targetId=Objects.requireNonNull(targetId);}
    public static void validateRequest(SyncJobDefinition.FrozenRequest r){
        if(r==null||!r.definition().equals(MoneyflowSyncJobOwner.DEFINITION)||!r.definition().jobId().equals("data.moneyflow")||r.definition().datasetVersion()!=MoneyflowDataset.DEFINITION.schemaVersion()
                ||!Set.of(Mode.INCREMENTAL,Mode.BACKFILL).contains(r.mode())||r.from()==null||r.to()==null||r.to().isAfter(r.logicalDate()))throw new IllegalArgumentException("Frozen bounded D024 request required");
        var p=r.parameters();Set<String> allowed=Set.of("targetId","trade_dates","checkpointAnchor","checkpointBefore","targetMinBefore","targetMaxBefore","targetRowsBefore");if(!allowed.containsAll(p.keySet())||!p.keySet().containsAll(Set.of("targetId","trade_dates","targetRowsBefore")))throw new IllegalArgumentException("Unexpected/missing frozen D024 parameter");
        if(!(p.get("targetId") instanceof String id)||!id.matches("static-v2-[0-9a-f]{64}")||!(p.get("targetRowsBefore") instanceof Integer count)||count<0)throw new IllegalArgumentException("Frozen D024 physical identity and nonnegative target row count required");
        long days=ChronoUnit.DAYS.between(r.from(),r.to())+1;if(days<1||days>MoneyflowSyncJobOwner.MAX_WINDOW_DAYS)throw new IllegalArgumentException("D024 window exceeds five calendar days");
        for(String field:List.of("checkpointAnchor","checkpointBefore","targetMinBefore","targetMaxBefore"))if(p.get(field)!=null&&!(p.get(field) instanceof LocalDate))throw new IllegalArgumentException("Invalid frozen D024 date "+field);
        LocalDate anchor=(LocalDate)p.get("checkpointAnchor"),before=(LocalDate)p.get("checkpointBefore");if(r.mode()==Mode.INCREMENTAL){if(anchor==null)throw new IllegalArgumentException("D024 incremental request requires checkpoint anchor");if(before==null&&!anchor.equals(r.from()))throw new IllegalArgumentException("D024 bootstrap must start at its frozen anchor");if(before!=null){LocalDate expected=before.minusDays(MoneyflowSyncJobOwner.REVISION_DAYS);if(expected.isBefore(anchor))expected=anchor;if(!r.from().equals(expected)||before.isBefore(anchor)||before.isAfter(r.to()))throw new IllegalArgumentException("D024 incremental window must reread two days before its checkpoint");}}else if(anchor==null||before!=null||r.from().isBefore(anchor))throw new IllegalArgumentException("D024 BACKFILL must carry a valid checkpoint/bootstrap anchor and no before marker");
        Object raw=p.get("trade_dates");if(!(raw instanceof String encoded)||encoded.isBlank()||encoded.length()>64)throw new IllegalArgumentException("Frozen D024 trade date sequence required");decodeDates(r);
    }
    public static List<LocalDate> decodeDates(SyncJobDefinition.FrozenRequest request){Object raw=request.parameters().get("trade_dates");if(!(raw instanceof String encoded)||encoded.equals("NONE")||encoded.isBlank())throw new IllegalArgumentException("D024 request requires at least one open source date");var dates=Arrays.stream(encoded.split(",",-1)).map(s->{if(!s.matches("[0-9]{8}"))throw new IllegalArgumentException("D024 dates must use YYYYMMDD");return LocalDate.parse(s,java.time.format.DateTimeFormatter.BASIC_ISO_DATE);}).toList();if(dates.size()>MoneyflowSyncJobOwner.MAX_WINDOW_DAYS||dates.stream().distinct().count()!=dates.size()||!dates.equals(dates.stream().sorted().toList())||dates.stream().anyMatch(d->d.isBefore(request.from())||d.isAfter(request.to())))throw new IllegalArgumentException("D024 source dates are duplicate, unordered or outside the frozen window");return dates;}
    @Override public void preflight(SyncJobDefinition.FrozenRequest request){validateRequest(request);if(!targetId.equals(request.parameters().get("targetId")))throw new IllegalStateException("Frozen D024 physical target differs from adapter target");if(!decodeDates(request).equals(calendar.read(request.from(),request.to())))throw new IllegalStateException("D024 exchange calendar changed after request freeze");port.preflight();}
    @Override public SyncJobRunner.SourceCompletion fetch(SyncJobDefinition.FrozenRequest request,SyncJobRunner.PageConsumer<Moneyflow> consumer,BooleanSupplier cancelled)throws Exception{
        var dates=decodeDates(request);var refs=new ArrayList<Map<String,Object>>();int total=0,pages=0;for(LocalDate date:dates){if(cancelled.getAsBoolean()||Thread.currentThread().isInterrupted())throw new CancellationException("D024 cancelled before daily source request");var page=source.fetch(date,cancelled);verifyNoSourceKeyRemoval(date,page.rows());consumer.accept(page);pages++;total=Math.addExact(total,page.rows().size());refs.add(Map.of("tradeDate",date.toString(),"rows",page.rows().size(),"sourceFingerprint",page.sourceFingerprint(),"responseEvidence",page.responseEvidence()));}
        if(pages!=dates.size()||total>MoneyflowSyncJobOwner.DEFINITION.budget().maxRows())throw new IllegalStateException("D024 date-slice/source row budget exceeded");Files.createDirectories(evidenceRoot);Path completion=evidenceRoot.resolve("complete-window.json");var proof=new LinkedHashMap<String,Object>();proof.put("dataset","moneyflow");proof.put("endpoint","moneyflow");proof.put("targetId",targetId);proof.put("mode",request.mode().name());proof.put("fromInclusive",request.from().toString());proof.put("toInclusive",request.to().toString());proof.put("tradeDates",dates);proof.put("completedDateSlices",pages);proof.put("sourceRows",total);proof.put("returnedRows",total);proof.put("submittedRows",total==0?0:null);proof.put("writeCandidateRows",total);proof.put("writeAccounting","Actual sends and reused rows are recorded by the runner/batch ledger; source completion does not infer insert or update counts");proof.put("sourceFingerprint",combine(refs.stream().map(r->(String)r.get("sourceFingerprint")).toList()));proof.put("sourceReceipts",refs);proof.put("sourceComplete",true);proof.put("dedup",true);proof.put("complete",true);JobDefinitionJson.mapper().writeValue(completion.toFile(),proof);return new SyncJobRunner.SourceCompletion(pages,total,true,completion.toString());
    }
    private void verifyNoSourceKeyRemoval(LocalDate date,List<Moneyflow> sourceRows){var sourceKeys=new HashSet<MoneyflowKey>();for(var row:sourceRows)if(!sourceKeys.add(row.key()))throw new IllegalStateException("D024 duplicate source key");var existing=port.readDate(date);if(existing.stream().anyMatch(row->!sourceKeys.contains(row.key())))throw new IllegalStateException("D024 source omitted a key already in the DEDUP target; deletion requires an explicit staged replacement policy");}
    private static String combine(List<String> values)throws Exception{var digest=java.security.MessageDigest.getInstance("SHA-256");for(String value:values){digest.update(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));digest.update((byte)0);}return HexFormat.of().formatHex(digest.digest());}
    @Override public VerifiedBatchExecutor.Codec<Moneyflow,MoneyflowKey> codec(){return MoneyflowWritePort.CODEC;}@Override public VerifiedBatchExecutor.Port<Moneyflow,MoneyflowKey> port(){return port;}
}
